    const msg = {
      id: uuidv4(),
      conversation_id: sessionId,
      role,
      body,
      created_at: new Date().toISOString(),
    };
    const bucket = ephemeralMessages.get(sessionId) || [];
    bucket.push(msg);
    ephemeralMessages.set(sessionId, bucket);
    return msg;
  }
  return Message.create({
    conversation_id: sessionId,
    role,
    body,
  });
}

