    if (!conv) return;
    if (!Array.isArray(conv.failedSteps)) conv.failedSteps = [];
    conv.failedSteps.push(step);
    return;
  }
  try {
    Conversation.appendFailedStep(sessionId, step);
  } catch (err) {
    console.error('[conversationState] appendFailedStep failed:', err.message);
  }
}

