  const sessionId = ephemeralByUser.get(userId);
  if (sessionId) closeEphemeral(sessionId);
}

module.exports = {
  getOrCreateSession,
  closeSession,
  abandonStale,
  getSessionMessages,
  addMessage,
  discardEphemeralForUser,
  findActiveSessionsForUser,
  isEphemeral,
};

