const { v4: uuidv4 } = require('uuid');
const Conversation = require('../models/Conversation');
const Message = require('../models/Message');
const User = require('../models/User');
const exporter = require('./conversationExporter');

const STALE_THRESHOLD_MINUTES = 30;

// Regex patterns that signal "your previous instruction didn't pan out".
// These are tuned to elderly-user phrasing — short, literal, lowercase-leaning.
// `['’]?` matches both straight and curly apostrophes (and dropped ones from
// autocorrect). Order doesn't affect correctness but cheaper patterns come
// first to short-circuit faster.
const FAILURE_PATTERNS = [
  /that\s+didn['’]?t\s+work/i,
  /that\s+didn['’]?t\s+help/i,
  /still\s+not\s+working/i,
  /nothing\s+happened/i,
  /same\s+thing/i,
  /\bi\s+don['’]?t\s+see\b/i,
  /\bit['’]?s\s+not\s+there\b/i,
  /there['’]?s\s+no\s+\w+\s+option/i,
  /there\s+is\s+no\s+\w+\s+option/i,
];

// Transient per-session state that doesn't need to survive a server reload.
// `lastIssuedStepBySession` holds the most recent step the agent issued so
// the next user turn can attribute a failure signal to it.
