    const summary = recent
      .map((s, i) => `  ${i + 1}. ${s.instruction || '(no text)'} — signalled "${s.signal || 'failure'}"`)
      .join('\n');
    lines.push(`Steps already known to have failed this session:\n${summary}`);
  }
  return `## FAILURE-SIGNAL CONTEXT\n${lines.join('\n\n')}\n\n`;
}

