13	function buildScreenContext(context) {
14	  if (context.screenShareActive) {
15	    return `\n## SCREEN SHARING IS ACTIVE\nThe user is sharing their screen with you right now. You can see their screen — call take_screenshot to capture and analyze what's on their screen. When they ask "can you see my screen?" or want help finding something, call take_screenshot FIRST before responding — do NOT guess or give generic instructions.\n`;
16	  }
17	  if (context.relayAgentConnected) {
