29	function cleanResponseMarkers(text) {
30	  let cleaned = text;
31	  let videos = null;
32	
33	  const ytMatch = cleaned.match(/YOUTUBE_VIDEOS:(\[[\s\S]*?\])/);
34	  if (ytMatch) {
35	    try { videos = JSON.parse(ytMatch[1]); } catch (e) { /* ignore */ }
36	    cleaned = cleaned.replace(/YOUTUBE_VIDEOS:\[[\s\S]*?\]/g, '').trim();
37	  }
38	
39	  cleaned = cleaned.replace(/VERIFIED_RESOURCES:\n[\s\S]*?(?=\n\n|$)/g, '').trim();
40	  cleaned = cleaned.replace(/NO_CURATED_RESOURCES:[\s\S]*?(?=\n\n|$)/g, '').trim();
41	
42	  return { text: cleaned, videos: videos && videos.length > 0 ? videos : null };
43	}
