1	const { v4: uuidv4 } = require('uuid');
2	const Conversation = require('../models/Conversation');
3	const Message = require('../models/Message');
4	const User = require('../models/User');
5	const exporter = require('./conversationExporter');
6	
7	const STALE_THRESHOLD_MINUTES = 30;
8	
9	/**
10	 * Anonymous users' conversations live only in memory and are discarded
11	 * when the session ends. Keyed by the ephemeral conversation id, which is
12	 * also returned to the client so the rest of the app can refer to it by
13	 * the same handle as persistent conversations.
14	 *
15	 * ephemeralConversations  : Map<conversationId, {id, user_id, status, started_at, ended_at}>
16	 * ephemeralMessages       : Map<conversationId, Array<{id, role, body, created_at}>>
17	 * ephemeralByUser         : Map<userId, conversationId>  (active session lookup)
18	 */
19	const ephemeralConversations = new Map();
20	const ephemeralMessages = new Map();
21	const ephemeralByUser = new Map();
22	
23	function isAnonymousUser(userId) {
24	  // All users get persistent conversations now — even anonymous ones.
25	  // As long as they have a session cookie, their chats persist in SQLite.
26	  // Only truly missing users (no DB row at all) go ephemeral.
27	  const user = User.findById(userId);
28	  return !user;
29	}
30	
31	function isEphemeral(sessionId) {
32	  return ephemeralConversations.has(sessionId);
33	}
34	
35	function createEphemeralSession(userId) {
36	  const id = uuidv4();
37	  const now = new Date().toISOString();
38	  const conv = {
39	    id,
40	    user_id: userId,
41	    status: 'active',
42	    task_type: null,
43	    context_summary: null,
44	    started_at: now,
45	    ended_at: null,
46	    ephemeral: true,
47	  };
48	  ephemeralConversations.set(id, conv);
49	  ephemeralMessages.set(id, []);
50	  ephemeralByUser.set(userId, id);
51	  return conv;
52	}
53	
54	function findActiveEphemeral(userId) {
55	  const id = ephemeralByUser.get(userId);
56	  if (!id) return null;
57	  const conv = ephemeralConversations.get(id);
58	  return conv && conv.status === 'active' ? conv : null;
59	}
60	
61	function closeEphemeral(sessionId) {
62	  const conv = ephemeralConversations.get(sessionId);
63	  if (!conv) return null;
64	  conv.status = 'completed';
65	  conv.ended_at = new Date().toISOString();
66	  // Wipe messages — anonymous users never persist to disk.
67	  ephemeralMessages.delete(sessionId);
68	  ephemeralConversations.delete(sessionId);
69	  if (ephemeralByUser.get(conv.user_id) === sessionId) {
70	    ephemeralByUser.delete(conv.user_id);
71	  }
72	  return conv;
73	}
74	
75	/**
76	 * Find the user's active conversation, or create a new one.
77	 */
78	function getOrCreateSession(userId) {
79	  if (isAnonymousUser(userId)) {
80	    const existing = findActiveEphemeral(userId);
81	    if (existing) return existing;
82	    return createEphemeralSession(userId);
83	  }
84	  const active = Conversation.findActive(userId);
85	  if (active && active.length > 0) {
86	    return active[0];
87	  }
88	  return Conversation.create({ user_id: userId });
89	}
90	
91	/**
92	 * Mark a conversation as completed and set ended_at. For ephemeral
93	 * sessions, this discards the in-memory state without touching the DB
94	 * or the exporter.
95	 */
96	function closeSession(sessionId) {
97	  if (isEphemeral(sessionId)) {
98	    return closeEphemeral(sessionId);
99	  }
100	
101	  const now = new Date().toISOString();
102	  const result = Conversation.update(sessionId, {
103	    status: 'completed',
104	    ended_at: now,
105	  });
106	
107	  try {
108	    exporter.exportConversation(sessionId);
109	  } catch (err) {
110	    console.error('[conversationState] Auto-export failed:', err.message);
111	  }
112	
113	  return result;
114	}
115	
116	function abandonStale() {
117	  return Conversation.abandonStale(STALE_THRESHOLD_MINUTES);
118	}
119	
120	/**
121	 * Return all active sessions for a user (DB for authenticated users,
122	 * ephemeral for anonymous).
123	 */
124	function findActiveSessionsForUser(userId) {
125	  if (isAnonymousUser(userId)) {
126	    const conv = findActiveEphemeral(userId);
127	    return conv ? [conv] : [];
128	  }
129	  return Conversation.findActive(userId);
130	}
131	
132	function getSessionMessages(sessionId, limit = 20) {
133	  if (isEphemeral(sessionId)) {
134	    const all = ephemeralMessages.get(sessionId) || [];
135	    return all.slice(-limit);
136	  }
137	  return Message.getRecent(sessionId, limit);
138	}
