function isEphemeral(sessionId) {
  return ephemeralConversations.has(sessionId);
}

function createEphemeralSession(userId) {
  const id = uuidv4();
  const now = new Date().toISOString();
  const conv = {
    id,
    user_id: userId,
    status: 'active',
    task_type: null,
    context_summary: null,
    started_at: now,
