  ephemeralByUser.set(userId, id);
  return conv;
}

function findActiveEphemeral(userId) {
  const id = ephemeralByUser.get(userId);
  if (!id) return null;
  const conv = ephemeralConversations.get(id);
  return conv && conv.status === 'active' ? conv : null;
}

