  ephemeralMessages.delete(sessionId);
  ephemeralConversations.delete(sessionId);
  if (ephemeralByUser.get(conv.user_id) === sessionId) {
    ephemeralByUser.delete(conv.user_id);
  }
  return conv;
}

/**
