const User = require('../models/User');
const Conversation = require('../models/Conversation');
const conversationState = require('../core/conversationState');

const {
  detectFailureSignal,
  recordIssuedStep,
  getLastIssuedStep,
  getFailedSteps,
  noteUserTurn,
  consumeFailureContext,
  resetFailureStateForTests,
  getOrCreateSession,
} = conversationState;

beforeEach(() => {
  jest.clearAllMocks();
