function setRequestScreenshotFn(fn) { _requestScreenshotFn = fn; }

if (!anthropicApiKey) {
  console.warn('[agentOrchestrator] ANTHROPIC_API_KEY is not set — AI calls will fail. Running in degraded mode.');
