            model: activeModel,
            max_tokens: 1024,
            system: systemPrompt,
            messages,
            tools,
          });
        }

        if (toolRounds >= MAX_TOOL_ROUNDS) {
          console.error(`[agentOrchestrator] Tool loop hit max (${MAX_TOOL_ROUNDS}) for user ${userId}`);
        }

        finalTextResponse = extractTextFromContent(response.content);
      }
    } catch (err) {
      console.error(`[agentOrchestrator] ${resolved.provider} API error:`, err.message);
      return { response: FALLBACK_RESPONSE, safetyAlert: null, guideId: null, stepSequence: null };
    }

    const cleaned = cleanResponseMarkers(finalTextResponse);
    finalTextResponse = cleaned.text;
    const videos = cleaned.videos;

    const vocabLevel = user.vocabulary_level || 'basic';
    const filteredResponse = filterResponse(finalTextResponse, vocabLevel, userId);

    if (!filteredResponse) {
      return { response: FALLBACK_RESPONSE, safetyAlert, guideId, stepSequence, endedConversationId, conversationId: sessionId };
    }

    conversationState.addMessage(sessionId, 'assistant', filteredResponse);

    trackQuality({ userId, sessionId, userMessage: text, agentResponse: filteredResponse, user });

    // Extract artifacts created during the tool-use loop
    const guide = getAndClearLastGuide();
    const findings = getAndClearLastFindings();
    const practice = getAndClearLastPractice();
    const screenshot = getAndClearLastScreenshot();
    if (guide) console.log(`[agentOrchestrator] Guide artifact: "${guide.title}" (${guide.steps?.length || 0} steps)`);
    if (findings) console.log(`[agentOrchestrator] Findings artifact: "${findings.title}" (${findings.findings?.length || 0} items)`);
    if (practice) console.log(`[agentOrchestrator] Practice artifact: "${practice.taskId || practice.title}"`);
    if (screenshot) console.log(`[agentOrchestrator] Screenshot: ${screenshot.found ? 'target found' : 'no target'} (${Math.round((screenshot.imageBase64?.length || 0) / 1024)}KB)`);

    // Flag system-modifying responses so the client can render a DisclaimerCard.
    // See server/core/systemModifyingDetector.js for the rule list.
    const sysModCheck = detectSystemModifying(
      `${filteredResponse}\n${flattenGuideText(guide)}`
    );

    return { response: filteredResponse, safetyAlert, guideId, stepSequence, endedConversationId, conversationId: sessionId, matchedSkillId: matchedSkillId || guideId, userOsType: user?.os_type, videos: videos && videos.length > 0 ? videos : null, guide: guide || null, findings: findings || null, practice: practice || null, screenshot: screenshot || null, confidence: skillMatch ? 'high' : 'low', systemModifying: sysModCheck.isModifying, systemModifyingMatches: sysModCheck.isModifying ? sysModCheck.matched : null };
  } catch (err) {
    console.error('[agentOrchestrator] Unexpected error:', err.message);
    return { response: FALLBACK_RESPONSE, safetyAlert: null, guideId: null, stepSequence: null, endedConversationId: null, conversationId: null };
  }
}

