      result = `Emergency flagged: ${args.reason}`;
    } catch (err) {
      console.error('[agentOrchestrator] Failed to log emergency:', err.message);
      result = 'Failed to log emergency event';
    }
  } else if (name === 'create_guide') {
    try {
