      const pcpalTools = require('../mcp/pcpalTools');
      if (pcpalTools._setLastPractice) pcpalTools._setLastPractice(practiceObj);
      else { _createdPractice = practiceObj; }
      result = `Practice started: "${args.custom_title || args.task_id}"`;
    } catch (err) {
