    input_schema: {
      type: 'object',
      properties: {
        dll_name: { type: 'string', description: "The DLL filename from the error, e.g. 'MSVCP140.dll', 'VCRUNTIME140.dll'" },
        error_text: { type: 'string', description: "The full error message text if available" },
